import { Result, ok, err } from '../kernel/result';
import { lookupOrder } from './order.service';

export function refundOrder(orderId: string): Result<void, string> {
  const order = lookupOrder(orderId);

  if (!order) {
    return err(`Order ${orderId} not found`);
  }

  if (order.refunded) {
    return err(`Order ${orderId} has already been refunded`);
  }

  if (order.total < 10) {
    return err(`Order ${orderId} total is ${order.total}, must be at least 10 to refund`);
  }

  (order as any).refunded = true;
  return ok(undefined);
}

